"""Original tubulointerstitial/cystic chapter: interstitial and inherited tubular disease."""
from qbank_authoring import question,ref,finalize
TI=ref('MSD Manual Professional: Tubulointerstitial Nephritis','https://www.msdmanuals.com/professional/nephrology/tubulointerstitial-diseases/tubulointerstitial-nephritis')
FA=ref('Fanconi Syndrome','https://www.ncbi.nlm.nih.gov/books/NBK534872/')
UM=ref('GeneReviews: ADTKD-UMOD','https://www.ncbi.nlm.nih.gov/books/NBK1356/')
NP=ref('GeneReviews: Nephronophthisis-Related Ciliopathies','https://www.ncbi.nlm.nih.gov/sites/books/NBK368475/')
