AR=ref('NCI: Aristolochic Acids','https://www.cancer.gov/about-cancer/causes-prevention/risk/substances/aristolochic-acids')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('Slow CKD progression is accompanied by a concentrating defect, polyuria and relatively modest proteinuria with bland sediment. Which compartment is particularly implicated?', 'Tubulointerstitium',[
 ('A purely nephrotic podocytopathy as the best pattern','That more often produces prominent albumin loss.'),('An acute necrotizing glomerular process as the best fit','Active hematuric sediment would be more characteristic.'),('A lower urinary tract infection as the complete explanation','This does not explain chronic progressive tubular dysfunction.')],
 'Tubular functions can fail before dramatic glomerular findings appear', '**Chronic interstitial disease can impair concentration and solute handling.**', ['Urinary abnormalities may be subtle.','Anemia and electrolyte disturbances can contribute to recognition.'], '**Search for exposure, obstruction and inheritance clues.**', ['Review drugs and recurrent infections.','Do not dismiss progressive disease because the dipstick is unimpressive.'], [['Concentration','Often impaired'],['Protein','Usually modest rather than nephrotic'],['Sediment','Can be bland']], [TI], 'clinical_scenario')
q('Normoglycemic glycosuria, hypophosphatemia, aminoaciduria and bicarbonate wasting occur together. Which syndrome is most likely?', 'Fanconi syndrome',[
 ('Isolated collecting-duct vasopressin resistance','That primarily causes a water-conservation defect.'),('An isolated glomerular albumin leak','This does not explain generalized solute wasting.'),('Type 4 RTA as the complete pattern','Hyperkalemic distal acidification dysfunction is a different mechanism.')],
 'Generalized proximal dysfunction causes multiple losses', '**The proximal tubule reabsorbs glucose, phosphate, bicarbonate and amino acids.**', ['Low-molecular-weight protein and urate losses can also occur.','Causes include inherited and acquired disorders.'], '**Identify and remove a treatable driver.**', ['Review drugs and monoclonal proteins in adults.','Replace deficits with monitoring.'], [['Site','Proximal tubule'],['Losses','Several filtered solutes'],['Work-up','Inherited/acquired causes']], [FA], 'clinical_scenario')
q('A patient on tenofovir disoproxil develops phosphate wasting and glycosuria despite normal blood glucose. What is the best next principle?', 'Assess tenofovir-associated proximal tubular toxicity and review the antiviral regimen with the treating team',[
 ('Diagnose diabetes solely from urine glucose','Normoglycemic glycosuria suggests tubular dysfunction.'),('A near-normal creatinine excludes drug toxicity','Tubular defects can precede marked filtration loss.'),('Stop all HIV treatment permanently without an alternative','An effective safe replacement strategy is needed.')],
 'Drug toxicity can be compartment-specific', '**TDF can cause proximal tubulopathy, including Fanconi syndrome.**', ['CKD, interacting agents and other factors can increase risk.','Phosphate loss can contribute to bone symptoms.'], '**Coordinate treatment and recovery monitoring.**', ['Review renal, urine and electrolyte findings.','Do not assume every tenofovir formulation has identical exposure and risk.'], [['Clue','Normoglycemic glycosuria'],['Additional loss','Phosphate'],['Action','Regimen and toxicity review']], [FA], 'clinical_scenario')
q('Long-term lithium use is followed by polyuria with dilute urine that does not appropriately concentrate. Which mechanism is particularly likely?', 'Nephrogenic vasopressin resistance',[
 ('Primary aldosterone deficiency as the direct explanation','This does not produce the typical lithium water defect.'),('Excess ADH causing persistent concentrated urine','The urine is dilute.'),('Glomerular IgA deposition as the expected mechanism','Lithium has a characteristic tubular effect.')],
 'A collecting-duct response defect impairs water conservation', '**Lithium can impair the renal response to vasopressin.**', ['Hypernatremia can develop if water access is limited.','Other causes of polyuria must be assessed.'], '**Review lithium and treat the water disorder safely.**', ['Amiloride may help selected lithium-related disease through specialist care.','Monitor volume, sodium, potassium and renal function.'], [['Drug','Lithium'],['Site','Collecting-duct water response'],['Risk','Water loss/hypernatremia']], [TI], 'clinical_scenario')
q('CKD develops during successful long-term lithium treatment. What is the appropriate general approach?', 'Joint renal and psychiatric review balancing kidney trajectory, toxicity episodes, alternatives and relapse risk',[
 ('Abrupt withdrawal is automatically safest for every patient','Psychiatric relapse and withdrawal planning matter.'),('Continue unchanged forever regardless of decline','Renal and exposure risks need reassessment.'),('A single creatinine value proves lithium is the only cause','Other CKD causes can coexist.')],
 'A drug can have both essential benefit and cumulative risk', '**Lithium can be associated with chronic tubulointerstitial injury.**', ['Toxicity episodes and exposure history are relevant.','Interactions and acute illness can increase levels.'], '**Use an individualized monitored plan.**', ['Adjust or replace treatment when appropriate.','Prevent dehydration and interacting-drug toxicity.'], [['Assessment','Trajectory and exposure'],['Psychiatric context','Relapse risk'],['Decision','Shared specialist plan']], [TI], 'clinical_scenario')
q('Long-term heavy mixed-analgesic exposure is accompanied by chronic interstitial disease and papillary necrosis. Which diagnosis is favored?', 'Analgesic nephropathy',[
 ('MCD as the only analgesic-related renal lesion','NSAIDs can cause several different lesions, but this chronic papillary pattern is distinct.'),('Primary IgAN','The exposure and papillary injury point elsewhere.'),('A normal dipstick would eliminate the diagnosis','Urinary findings can be modest.')],
 'The pattern differs from acute hemodynamic NSAID injury', '**Classic analgesic nephropathy combines chronic interstitial injury and papillary damage.**', ['Historical phenacetin-containing combinations are important.','Sloughed papillae can cause hematuria or obstruction.'], '**Stop harmful exposure and assess complications.**', ['Review alternate causes of papillary necrosis.','Provide appropriate pain and CKD care.'], [['Pattern','Chronic interstitial/papillary'],['Exposure','Heavy cumulative analgesic use'],['Complications','Hematuria/obstruction']], [AN], 'clinical_scenario')
q('Progressive interstitial nephropathy follows use of an herbal product containing aristolochic acid. Which additional risk is especially important?', 'Upper urinary tract urothelial malignancy',[
 ('Only transient benign cystitis','The carcinogenic association is important.'),('A protective effect against urinary cancer','This reverses the evidence.'),('A unique association with pituitary adenoma','That is not the relevant toxicity pattern.')],
 'A botanical exposure can be both nephrotoxic and carcinogenic', '**Aristolochic acid can cause renal fibrosis and urothelial cancer.**', ['Exposure can be hidden in mixed products.','Risk can remain after cessation.'], '**Remove exposure and arrange appropriate follow-up.**', ['Document the product and counsel against re-exposure.','Specialist cancer-risk evaluation may be needed.'], [['Kidney','Fibrosing nephropathy'],['Cancer','Urothelial tract'],['Prevention','Avoid further exposure']], [AR], 'clinical_scenario')
q('Autosomal dominant CKD with bland urine and early hyperuricemia/gout suggests which genetic disorder?', 'ADTKD-UMOD',[
 ('ADPKD as the uniquely required diagnosis','Marked bilateral cystic enlargement is not the stated phenotype.'),('Alport disease as the most characteristic pattern','Hematuria and collagen-related extrarenal findings are more typical.'),('Primary membranous nephropathy','Heavy albuminuria rather than bland familial interstitial disease is expected.')],
 'Gout can precede advanced filtration loss in a hereditary tubulopathy', '**UMOD variants cause a form of autosomal dominant tubulointerstitial kidney disease.**', ['Urine is often bland with little blood or protein.','Kidney failure age varies.'], '**Confirm through a suitable genetics pathway.**', ['Family counseling and donor assessment can change.','Avoid assuming a normal ultrasound excludes hereditary disease.'], [['Inheritance','Autosomal dominant'],['Urine','Bland'],['Clue','Early gout/hyperuricemia']], [UM], 'clinical_scenario')
q('A dominant familial bland-urine CKD remains unexplained after routine sequencing. Why might ADTKD-MUC1 need separate testing?', 'The pathogenic repeat-region mechanism may not be detected by standard sequencing panels',[
 ('Every negative panel excludes all ADTKD','Assay coverage is not universal.'),('MUC1 disease requires nephrotic proteinuria','The urine can be bland.'),('Kidney cysts are mandatory before testing','Older cystic terminology does not define every case.')],
 'A genetic test has a method-specific blind spot', '**Specialized MUC1 testing can be needed.**', ['Interpret the laboratory’s actual coverage.','UMOD, REN and other causes have overlapping phenotypes.'], '**Use family and clinical evidence to guide further testing.**', ['Avoid uninformative repeat tests with identical limitations.','Offer counseling about residual uncertainty.'], [['Phenotype','Dominant interstitial CKD'],['Routine panel','May miss MUC1 mechanism'],['Next step','Specialized testing']], [UM])
q('A child develops polyuria, growth impairment and progressive CKD with relatively small or normal-sized echogenic kidneys and possible corticomedullary cysts. Which inherited category is important?', 'Nephronophthisis-related ciliopathy',[
 ('Typical adult ADPKD alone','That usually has a different inheritance and enlarged-cystic pattern.'),('MCD','This does not explain the progressive concentrating defect and imaging phenotype.'),('An isolated lower UTI','This does not account for the chronic multisystem context.')],
 'Cystic disease need not produce large kidneys', '**Nephronophthisis is usually an autosomal recessive ciliopathy.**', ['Retinal, neurological or hepatic findings can identify related syndromes.','Cysts may not be obvious early.'], '**Use phenotype-informed genetic assessment.**', ['Manage fluid, nutrition and CKD complications.','Plan family counseling and KRT when needed.'], [['Inheritance','Usually recessive'],['Kidneys','Not necessarily enlarged'],['Systemic clues','Other ciliopathy features']], [NP], 'clinical_scenario')
q('Interstitial nephritis is followed by painful red eyes and uveitis in a young adult. Which syndrome should be considered?', 'Tubulointerstitial nephritis and uveitis syndrome',[
 ('Anti-GBM disease as the defining renal-ocular association','That is classically pulmonary-renal rather than this uveitic syndrome.'),('ADPKD','It does not typically explain inflammatory uveitis with TIN.'),('MCD','The biopsy compartment and eye inflammation differ.')],
 'Kidney and ocular inflammation may not begin simultaneously', '**TINU requires exclusion of systemic mimics.**', ['Sarcoidosis and infections are important alternatives.','Ocular symptoms can precede or follow renal disease.'], '**Coordinate ophthalmology and renal care.**', ['Treat each organ’s activity appropriately.','Monitor for recurrence and delayed eye disease.'], [['Kidney','Interstitial nephritis'],['Eye','Uveitis'],['Differential','Sarcoidosis/infection']], [TI], 'clinical_scenario')
q('Granulomatous interstitial nephritis occurs with hypercalcemia and systemic sarcoidosis features. Which mechanism can contribute to the calcium abnormality?', 'Extrarenal calcitriol production by activated granulomatous cells',[
 ('Mandatory excess PTH production from every granuloma','PTH is often suppressed in this mechanism.'),('A primary glomerular albumin leak as the sole cause','This does not explain calcitriol-driven hypercalcemia.'),('A normal serum ACE excludes the process','ACE is not a reliable exclusion test.')],
 'Interstitial inflammation and mineral physiology can be linked', '**Sarcoidosis can injure kidneys through granulomatous inflammation and calcium-related effects.**', ['Hypercalciuria and stones may occur.','Infection and drug-induced granulomas are important mimics.'], '**Confirm the systemic context before immunosuppression.**', ['Assess calcium, vitamin D metabolites and organ disease as appropriate.','Treat the cause and complications.'], [['Granuloma','Calcitriol production'],['Calcium','Can rise'],['Kidney','TIN and calcium injury']], [TI], 'clinical_scenario')
q('Renal dysfunction, low complement and bilateral cortical lesions occur with autoimmune pancreatitis and lymphoplasmacytic storiform interstitial fibrosis. Which disease is favored?', 'IgG4-related tubulointerstitial nephritis',[
 ('Isolated primary MCD','The systemic fibroinflammatory context and interstitial biopsy differ.'),('Typical bacterial pyelonephritis as the only explanation','The pathology and multisystem features favor another process.'),('ADPKD','The lesions and histology are not a cystic genetic pattern.')],
 'A systemic fibroinflammatory disease can involve renal interstitium', '**IgG4-related disease needs clinicopathological correlation.**', ['Serum IgG4 alone is neither fully sensitive nor specific.','Malignancy and infection can mimic the presentation.'], '**Use an appropriate tissue and systemic assessment.**', ['Treatment often responds to immune therapy but relapse can occur.','Avoid diagnosing from a raised IgG4 value alone.'], [['Clue','Systemic fibroinflammatory disease'],['Tissue','Lymphoplasmacytic/storiform pattern'],['Diagnosis','Integrated assessment']], [TI], 'clinical_scenario')
q('Asymmetric renal scars, hypertension and CKD follow childhood vesicoureteric reflux and recurrent pyelonephritis. Which process is most likely?', 'Reflux-associated chronic tubulointerstitial damage',[
 ('Primary diffuse podocytopathy as the only cause','The anatomical and infection history points elsewhere.'),('Acute anti-GBM disease','The chronic scar pattern differs.'),('Every adult UTI necessarily produces this degree of scarring','Risk and anatomy matter.')],
 'Structural urinary disease can leave long-term parenchymal injury', '**Reflux nephropathy can cause asymmetry, scars and reduced nephron mass.**', ['Hypertension and secondary proteinuria can develop.','Some congenital dysplasia overlaps with the history.'], '**Address current risks rather than treating an old label alone.**', ['Assess obstruction, recurrent infection, BP and kidney protection.','Avoid unnecessary prolonged antibiotics without a defined indication.'], [['History','Reflux/childhood infection'],['Imaging','Asymmetric scars'],['Care','Current anatomy and CKD risks']], [TI], 'clinical_scenario')
